<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Deposit', href: '/owner/deposits' }, { title: 'Buat settlement', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    type Line = { key: string; kind: string };
    let { deposit, invoices }: { deposit: { id: number; resident: string | null; required_amount_rupiah: number; balance_rupiah: number }; invoices: { id: number; invoice_number: string; due_date: string; balance_rupiah: number }[] } = $props();
    let lines = $state<Line[]>([{ key: 'line-0', kind: 'refund' }]);
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
    function addLine(): void { lines = [...lines, { key: crypto.randomUUID(), kind: 'refund' }]; }
    function removeLine(key: string): void { if (lines.length > 1) lines = lines.filter((line) => line.key !== key); }
</script>

<AppHead title="Buat settlement deposit" />
<main class="mx-auto w-full max-w-4xl space-y-6 p-4 md:p-8">
    <header class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Deposit · {deposit.resident ?? 'Penyewa'}</p><h1 class="text-3xl font-semibold tracking-tight">Proposal settlement</h1><p class="text-sm text-muted-foreground">Saldo liability saat ini {money(deposit.balance_rupiah)}. Catat pemeriksaan keluar dan item settlement satu per satu.</p></header>
    <Form action={`/owner/deposits/${deposit.id}/settlements`} method="post" class="space-y-5 rounded-xl border bg-card p-5 shadow-sm" enctype="multipart/form-data">{#snippet children({ errors, processing })}<div class="space-y-2"><label for="exit_inspection_notes" class="text-sm font-medium">Catatan inspeksi keluar</label><textarea id="exit_inspection_notes" name="exit_inspection_notes" required minlength="3" maxlength="4000" rows={4} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.exit_inspection_notes} /></div><div class="space-y-4">{#each lines as line, index (line.key)}<fieldset class="space-y-4 rounded-lg border p-4"><legend class="px-2 text-sm font-semibold">Item settlement {index + 1}</legend><div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for={`line_kind_${index}`} class="text-sm font-medium">Jenis</label><select id={`line_kind_${index}`} name={`lines[${index}][kind]`} bind:value={line.kind} required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="refund">Saldo tidak disengketakan untuk refund</option><option value="invoice_deduction">Pelunasan tagihan jatuh tempo dari deposit</option><option value="damage_deduction">Deduction kerusakan aktual</option><option value="held_claim">Klaim kerusakan sementara</option></select><InputError message={errors[`lines.${index}.kind`]} /></div><div class="space-y-2"><label for={`line_amount_${index}`} class="text-sm font-medium">Nominal (Rupiah)</label><Input id={`line_amount_${index}`} name={`lines[${index}][amount_rupiah]`} type="number" min={1} max={deposit.balance_rupiah} step={1} required /><InputError message={errors[`lines.${index}.amount_rupiah`]} /></div>{#if line.kind === 'invoice_deduction'}<div class="space-y-2 sm:col-span-2"><label for={`line_invoice_${index}`} class="text-sm font-medium">Tagihan jatuh tempo</label><select id={`line_invoice_${index}`} name={`lines[${index}][invoice_id]`} required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Pilih invoice</option>{#each invoices as invoice (invoice.id)}<option value={invoice.id}>{invoice.invoice_number} · jatuh tempo {invoice.due_date} · sisa {money(invoice.balance_rupiah)}</option>{/each}</select><InputError message={errors[`lines.${index}.invoice_id`]} /></div>{/if}<div class="space-y-2 sm:col-span-2"><label for={`line_reason_${index}`} class="text-sm font-medium">Alasan / rincian item</label><Input id={`line_reason_${index}`} name={`lines[${index}][reason]`} minlength={3} maxlength={1000} required /><InputError message={errors[`lines.${index}.reason`]} /></div>{#if ['invoice_deduction', 'damage_deduction', 'held_claim'].includes(line.kind)}<div class="space-y-2 sm:col-span-2"><label for={`line_basis_${index}`} class="text-sm font-medium">Dasar perjanjian tertulis</label><textarea id={`line_basis_${index}`} name={`lines[${index}][agreement_basis]`} required minlength="3" maxlength="2000" rows={2} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors[`lines.${index}.agreement_basis`]} /></div>{/if}{#if ['damage_deduction', 'held_claim'].includes(line.kind)}<div class="space-y-2 sm:col-span-2"><label for={`line_evidence_${index}`} class="text-sm font-medium">Bukti privat (PDF/JPG/PNG/WEBP, maks. 10 MB per file)</label><input id={`line_evidence_${index}`} name={`lines[${index}][evidence][]`} type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple required class="block w-full rounded-md border bg-background p-2 text-sm" /><InputError message={errors[`lines.${index}.evidence`]} /><InputError message={errors[`lines.${index}.evidence.0`]} /></div>{/if}</div>{#if lines.length > 1}<div class="flex justify-end"><Button type="button" variant="outline" onclick={() => removeLine(line.key)}>Hapus item</Button></div>{/if}</fieldset>{/each}</div><Button type="button" variant="outline" onclick={addLine}>Tambah item settlement</Button><InputError message={errors.lines} /><InputError message={errors.deposit} /><div class="rounded-lg bg-muted/40 p-4 text-sm text-muted-foreground">Refund saldo tidak disengketakan ditargetkan paling lambat hari ke-7. Klaim yang didukung bukti diselesaikan paling lambat hari ke-30; tidak ada refund otomatis.</div><div class="flex justify-end gap-2"><Link href={`/owner/deposits/${deposit.id}`} class="inline-flex items-center rounded-md border px-4 py-2 text-sm">Batal</Link><Button type="submit" disabled={processing}>{processing ? 'Menyimpan…' : 'Buat draft settlement'}</Button></div>{/snippet}</Form>
</main>
